import (
	"fmt"
)

resp, err := client.OrderFlags().ListOrderFlags(ctx, map[string]any{"limit": 20}, nil)
if err != nil {
	log.Fatal(err)
}
for _, row := range resp.Map().(map[string]any)["order_flags"].([]any) {
	flag := row.(map[string]any)
	fmt.Println(flag["id"], flag["name"], flag["color"])
}

